{
  "claims": [
    {
      "quote": "Now she’s 30, and her private, Palo Alto-based corporation, called Theranos–the name is an amalgam of the words “therapy” and “diagnosis”–has 500 employees and has raised more than $400 million from equity sales to investors who have effectively valued the company at more than $9 billion.",
      "kind": "specific",
      "why": "Checkable numbers include her age, employee count, funding raised, and company valuation."
    },
    {
      "quote": "Theranos today is a potentially highly disruptive upstart in America’s $73 billion diagnostic-lab industry, which performs nearly 10 billion tests a year and is estimated to provide the basis for about 70% of doctors’ medical decisions.",
      "kind": "specific",
      "why": "Checkable industry figures include the market size, total tests performed, and percentage of medical decisions."
    },
    {
      "quote": "Medicare and Medicaid each pay roughly $10 billion annually on reimbursements for these tests.",
      "kind": "specific",
      "why": "Checkable amounts include the annual Medicare and Medicaid reimbursement figures."
    },
    {
      "quote": "It currently offers more than 200–and is ramping up to offer more than 1,000–of the most commonly ordered blood diagnostic tests, all without the need for a syringe.",
      "kind": "specific",
      "why": "Checkable figures include the number of blood tests currently and planned to be offered."
    },
    {
      "quote": "The company has performed as many as 70 different tests from a single draw of 25 to 50 microliters collected in a tiny vial the size of an electric fuse, which Holmes has dubbed a “nanotainer.”",
      "kind": "specific",
      "why": "Checkable details include the number of tests performed and the sample volume collected."
    },
    {
      "quote": "Its phlebotomists currently take physician-ordered blood draws (and saliva, urine, feces, and other samples) at collection centers the company operates at its headquarters in Palo Alto and at 21 Walgreens–one in Palo Alto and the rest in Phoenix.",
      "kind": "specific",
      "why": "Checkable locations include the headquarters and the specific number of Walgreens collection centers."
    },
    {
      "quote": "Precisely how Theranos accomplishes all these amazing feats is a trade secret.",
      "kind": "redflag",
      "why": "Secrecy is given as the reason nothing can be checked about how the technology works.",
      "signal": "secrecy"
    },
    {
      "quote": "“I knew she was different,” Robertson told me in an interview.",
      "kind": "vague",
      "why": "This statement relies entirely on subjective praise with no checkable anchor."
    }
  ]
}

